//! Init config rendering: generated pretender.toml and GitHub workflow.
//!
//! # Responsibilities
//! Render the generated config document from resolved init options, emit
//! the preset threshold tables (default vs strict), and provide the
//! GitHub Actions workflow contents.
//!
//! # Rationale
//! Split from init/mod.rs so both files stay within the interim file-size
//! limit; templates, values, and the workflow YAML were moved verbatim to
//! keep generated bytes identical.
use super::{InitOptions, ThresholdPreset};
use crate::cli::args::ModeArg;

fn mode_label(mode: ModeArg) -> &'static str {
    match mode {
        ModeArg::Guidance => "guidance",
        ModeArg::Tiered => "tiered",
        ModeArg::Gate => "gate",
    }
}

fn quoted_language_list(options: &InitOptions) -> String {
    options
        .languages
        .iter()
        .map(|language| format!("\"{language}\""))
        .collect::<Vec<_>>()
        .join(", ")
}

pub(super) fn render_init_config(options: &InitOptions) -> String {
    let mode = mode_label(options.mode);
    let languages = quoted_language_list(options);

    format!(
        concat!(
            "[pretender]\n",
            "mode = \"{mode}\"\n",
            "languages = [{languages}]\n",
            "exclude = [\"vendor/**\", \"node_modules/**\", \"**/*_generated.*\"]\n\n",
            "[roles.test]\n",
            "paths = [\"tests/**\", \"**/*_test.*\", \"spec/**\"]\n\n",
            "[roles.library]\n",
            "paths = [\"pkg/**\", \"lib/**\"]\n\n",
            "[roles.script]\n",
            "paths = [\"scripts/**\", \"examples/**\"]\n\n",
            "[roles.generated]\n",
            "paths = [\"**/*.pb.go\", \"**/*_generated.*\"]\n\n",
            "[roles.vendor]\n",
            "paths = [\"vendor/**\", \"node_modules/**\"]\n\n",
            "{thresholds}"
        ),
        mode = mode,
        languages = languages,
        thresholds = preset_tables(options.preset),
    )
}

/// Single source for the threshold tables `init` emits (update-app-threshold-
/// defaults): emitting them explicitly makes the generated config self-
/// documenting and pins today's values against future default changes.
/// Strict deviations are pinned by the spec ("Strict Preset Values"); every
/// other value matches the built-in defaults.
fn preset_tables(preset: ThresholdPreset) -> String {
    let strict = preset == ThresholdPreset::Strict;
    app_preset_table(strict) + &test_preset_table(strict)
}

/// The `[thresholds]` app table; `strict` picks the pinned strict values.
fn app_preset_table(strict: bool) -> String {
    let v = |strict_val, default_val| if strict { strict_val } else { default_val };
    format!(
        concat!(
            "[thresholds]\n",
            "cyclomatic_max = {app_cyclomatic}\n",
            "cognitive_max = {app_cognitive}\n",
            "function_lines_max = {app_function_lines}\n",
            "file_lines_max = {app_file_lines}\n",
            "nesting_max = {app_nesting}\n",
            "params_max = {app_params}\n",
            "abc_max = {app_abc}\n",
            "duplication_pct_max = {app_duplication}\n",
            "void_mutators_max = 3\n",
            "mut_ratio_max = 0.3\n",
            "unwrap_max = 5\n",
            "bool_cluster_max = 3\n",
            "primitive_param_check = false\n",
            "inheritance_depth_max = 2\n\n",
        ),
        app_cyclomatic = v(8, 10),
        app_cognitive = v(12, 15),
        app_function_lines = v(25, 30),
        app_file_lines = v(300, 400),
        app_nesting = v(2, 3),
        app_params = v(3, 4),
        app_abc = v(25, 30),
        app_duplication = v(4, 5),
    )
}

/// The `[thresholds.test]` table; `strict` picks the pinned strict values.
fn test_preset_table(strict: bool) -> String {
    let v = |strict_val, default_val| if strict { strict_val } else { default_val };
    format!(
        concat!(
            "[thresholds.test]\n",
            "cyclomatic_max = {test_cyclomatic}\n",
            "cognitive_max = {test_cognitive}\n",
            "function_lines_max = {test_function_lines}\n",
            "nesting_max = 2\n",
            "params_max = 2\n",
            "duplication_pct_max = 30\n",
            "min_assertions = 1\n",
            "mock_count_max = 5\n",
            "unwrap_max = 5\n",
            "lazy_cluster_min = 3\n"
        ),
        test_cyclomatic = v(2, 3),
        test_cognitive = v(3, 5),
        test_function_lines = v(60, 80),
    )
}

/// Generated GitHub Actions workflow, verbatim since pretender-fb3.
const GITHUB_CI_WORKFLOW_CONTENTS: &str = r#"name: Pretender

on:
  pull_request:
  push:
    branches:
      - main

jobs:
  pretender:
    runs-on: ubuntu-latest
    permissions:
      contents: read
      security-events: write
    steps:
      - uses: actions/checkout@v4
      - uses: dtolnay/rust-toolchain@stable
      - name: Install Pretender
        run: cargo install --git https://github.com/charly-vibes/pretender --locked pretender
      - name: Run Pretender
        id: pretender
        continue-on-error: true
        run: pretender check . --format=sarif --output=pretender.sarif
      - name: Upload SARIF
        uses: github/codeql-action/upload-sarif@v3
        with:
          sarif_file: pretender.sarif
      - name: Append markdown report
        if: steps.pretender.outcome == 'failure'
        run: pretender report --format=markdown >> $GITHUB_STEP_SUMMARY
      - name: Fail on Pretender findings
        if: steps.pretender.outcome == 'failure'
        run: exit 1
"#;

/// The workflow YAML written by `pretender ci generate` and `init`.
pub(crate) fn github_ci_workflow_contents() -> &'static str {
    GITHUB_CI_WORKFLOW_CONTENTS
}
